#pragma once
#include "industry_topic_store.hpp"
namespace industryTopicUpdate {
inline QJsonObject sourceRow(QJsonObject wrapper){need(wrapper.value("kind").isString()&&wrapper.value("id").isString()&&wrapper.value("raw").isString(),"本机来源原包装缺失");auto raw=wrapper.value("raw").toString();watchlistBackup::JsonGate{raw}.run();auto r=json(parse(raw)).toObject();need(r.value("id")==wrapper.value("id"),"本机来源原身份冲突");return r;}
inline QMap<QString,QJsonObject> sourceMap(QJsonArray records){QMap<QString,QJsonObject> out;for(auto v:records){auto w=v.toObject();auto kind=w.value("kind").toString();if(!QStringList{"docs","collections","reports"}.contains(kind))continue;sourceRow(w);auto key=kind+":"+w.value("id").toString();need(!out.contains(key),"本机来源身份重复");out.insert(key,w);}return out;}
inline QJsonArray sourceCatalogue(QJsonArray records,bool baselines=false){QJsonArray out;auto rows=sourceMap(records);for(auto i=rows.cbegin();i!=rows.cend();++i){auto r=sourceRow(i.value());if(baselines){if(i.key().startsWith("reports:")&&r.value("legacySource")=="industry_research_archive")out.append(QJsonObject{{"id",i.key()},{"title",r.value("title").toString(i.key())}});}else if(!i.key().startsWith("reports:"))out.append(QJsonObject{{"id",i.key()},{"title",r.value("title").toString(i.key())},{"sourceUrl",r.value("sourceUrl").toString(r.value("url").toString())},{"legacySource",r.value("legacySource").toString()},{"hasFullText",r.value("text").isString()&&!r.value("text").toString().isEmpty()}});}return out;}
inline QString sourceBaseline(QJsonArray records,QString id){auto rows=sourceMap(records);need(rows.contains(id)&&id.startsWith("reports:"),"完整产业基线已缺失");auto r=sourceRow(rows.value(id));need(r.value("legacySource")=="industry_research_archive"&&r.value("text").isString(),"所选原件不是完整产业档案");auto full=r.value("text").toString();industryArchive::validate(full);return full;}
inline QString sourceVersion(QJsonArray records,QJsonArray selected){auto rows=sourceMap(records);QStringList ids;QSet<QString>seen;for(auto v:selected){auto id=v.toString();need(v.isString()&&QRegularExpression("^(docs|collections):.{1,200}$").match(id).hasMatch()&&!seen.contains(id),"所选来源身份无效/重复");seen.insert(id);ids.append(id);}std::sort(ids.begin(),ids.end());QJsonArray parts;for(auto id:ids)parts.append(QJsonObject{{"id",id},{"raw",rows.contains(id)?rows.value(id).value("raw"):QJsonValue(QJsonValue::Null)}});return watchlistWorkspace::hash(parts);}
inline V sourceAcquire(QJsonArray records,QJsonObject task,QString at){unifiedBackup::time(at);auto rows=sourceMap(records);auto ids=task.value("sourceIds").toArray();sourceVersion(records,ids);QMap<QString,QJsonArray>matching;for(auto v:ids){auto id=v.toString();if(!rows.contains(id))continue;auto w=rows.value(id),r=sourceRow(w);QString body=r.value("text").toString(),source=r.value("sourceUrl").toString(r.value("url").toString()),origin="native-local-selected-body";auto pub=r.value("publishedAt"),fetched=r.value("fetchedAt");if(r.value("legacySource")=="industry_research_evidence"){auto original=r.value("legacyOriginal").toObject();need(original.value("payload").isObject(),"F03证据原件缺失");auto p=original.value("payload").toObject();body=p.value("text").toString();source=original.value("canonicalUrl").toString();pub=p.value("publishedAt");fetched=p.value("fetchedAt");need(body.isEmpty()||QString::fromLatin1(QCryptographicHash::hash(body.toUtf8(),QCryptographicHash::Sha256).toHex())==original.value("contentSha256").toString(),"F03证据全文摘要不符");origin="native-local-retained-industry-evidence";}if(body.isEmpty()||source.isEmpty())continue;QString canonical;try{canonical=url(source);}catch(...){continue;}industryArchive::time(pub,false);industryArchive::time(fetched,false);if(fetched.isString()&&!fetched.toString().isEmpty())need(industryArchive::noLater(fetched.toString(),at),"来源原获取时刻晚于本次cutoff");QJsonObject item{{"requestedUrl",canonical},{"canonicalUrl",canonical},{"finalUrl",canonical},{"title",r.value("title").toString(id)},{"text",body},{"contentSha256",QString::fromLatin1(QCryptographicHash::hash(body.toUtf8(),QCryptographicHash::Sha256).toHex())},{"publishedAt",pub.isUndefined()?QJsonValue(QJsonValue::Null):pub},{"fetchedAt",fetched.isString()&&!fetched.toString().isEmpty()?fetched:QJsonValue(at)},{"localReadAt",at},{"originalFetchedAt",fetched.isUndefined()?QJsonValue(QJsonValue::Null):fetched},{"origin",origin},{"sourceId",id},{"sourceRecordSha256",QString::fromLatin1(QCryptographicHash::hash(w.value("raw").toString().toUtf8(),QCryptographicHash::Sha256).toHex())},{"locator",QJsonObject{{"type","native-selected-full-text"},{"offsetUnit","UTF16 legacy normalizeText"}}},{"extractor","native-local-full-body"}};matching[canonical].append(item);}QJsonArray out;for(auto u:task.value("sourceUrls").toArray()){auto requested=url(u.toString());auto candidates=matching.value(requested);if(candidates.size()==1)out.append(candidates.first());else out.append(QJsonObject{{"requestedUrl",requested},{"errorCode",candidates.isEmpty()?"SELECTED_FULL_SOURCE_UNAVAILABLE":"SELECTED_SOURCE_URL_AMBIGUOUS"}});}auto acquired=value(out);for(auto&source:acquired.values)if(get(source,"locator").kind==V::Object)set(source,"locator",object({{"type",value("native-selected-full-text")},{"offsetUnit",value("UTF16 legacy normalizeText")}}));return acquired;}
}
